@media (min-width: 721px) and (max-width: 899px) {
  .upload-form { flex-wrap: wrap; }
  /* Ellipsis preview wraps to 2 rows here; filled numbers need 3. Reserve the
     taller slot so Load → geometry does not grow the header. */
  .params:not(:empty) {
    min-height: 76px;
  }
  /* Keep ε/δ + Load on one row; tooltips and start copy still explain match/grid. */
  .upload-form .param-gloss { display: none; }
}

input.new_string:
@media (min-width: 721px) and (max-width: 899px) {
  .upload-form { flex-wrap: wrap; }
  /* Ellipsis preview wraps to 2 rows here; filled numbers need 3. Reserve the
     taller slot so Load → geometry does not grow the header. */
  .params:not(:empty) {
    min-height: 76px;
  }
  /* Prefer plain Match / Grid over bare ε / δ. Hide the Greek symbols and
     shrink the number fields so Load stays on the same control row. */
  .upload-form .param-symbol { display: none; }
  .upload-form .param-gloss {
    display: inline;
    color: var(--text);
    font-weight: 600;
    text-transform: capitalize;
  }
  .upload-form label input[type="number"] {
    width: 50px;
  }
}

