import { chromium } from 'playwright';
import path from 'path';
import { pathToFileURL } from 'url';

const root = process.cwd();
const fixture = pathToFileURL(path.join(root, 'web/usability/narrow-match-grid-labels.html')).href;
const index = pathToFileURL(path.join(root, 'web/index.html')).href;

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 820, height: 700 } });

await page.goto(fixture);
const check = await page.locator('#check').innerText();
console.log('FIXTURE:', check);

await page.goto(index);
await page.waitForTimeout(200);
const formMetrics = await page.evaluate(() => {
  const form = document.querySelector('.upload-form');
  const epsLabel = document.querySelector('label[for], #epsilonInput')?.closest('label')
    || document.querySelector('#epsilonInput')?.closest('label');
  const deltaLabel = document.querySelector('#deltaInput')?.closest('label');
  const loadBtn = document.querySelector('#loadBtn');
  const symbol = epsLabel?.querySelector('.param-symbol');
  const gloss = epsLabel?.querySelector('.param-gloss');
  const symbolStyle = symbol ? getComputedStyle(symbol) : null;
  const glossStyle = gloss ? getComputedStyle(gloss) : null;
  const symbolHidden = !symbol || symbolStyle.display === 'none' || symbol.getBoundingClientRect().width < 1;
  const glossVisible = !!gloss && glossStyle.display !== 'none' && gloss.getBoundingClientRect().width > 1;
  const glossText = gloss ? gloss.textContent.trim() : '';
  const loadRect = loadBtn.getBoundingClientRect();
  const epsRect = epsLabel.getBoundingClientRect();
  const deltaRect = deltaLabel.getBoundingClientRect();
  // Same row if vertical centers are close
  const sameRow = Math.abs(loadRect.top - epsRect.top) < 20
    && Math.abs(deltaRect.top - epsRect.top) < 20;
  return {
    scrollWidth: document.documentElement.scrollWidth,
    symbolHidden,
    glossVisible,
    glossText,
    sameRow,
    loadTop: Math.round(loadRect.top),
    epsTop: Math.round(epsRect.top),
    formWrap: getComputedStyle(form).flexWrap,
  };
});
console.log('INDEX820:', JSON.stringify(formMetrics));

// Also check 1280 still shows both symbol+gloss
await page.setViewportSize({ width: 1280, height: 800 });
await page.waitForTimeout(100);
const wide = await page.evaluate(() => {
  const epsLabel = document.querySelector('#epsilonInput')?.closest('label');
  const symbol = epsLabel?.querySelector('.param-symbol');
  const gloss = epsLabel?.querySelector('.param-gloss');
  return {
    symbolVisible: symbol && getComputedStyle(symbol).display !== 'none' && symbol.getBoundingClientRect().width > 1,
    glossVisible: gloss && getComputedStyle(gloss).display !== 'none' && gloss.getBoundingClientRect().width > 1,
    text: epsLabel?.innerText?.replace(/\s+/g, ' ').trim(),
  };
});
console.log('INDEX1280:', JSON.stringify(wide));

await browser.close();
EOF
